const fs=require('node:fs'),path=require('node:path');
module.exports=function(root){
 const now=new Date(),monday=new Date(now.getFullYear(),now.getMonth(),now.getDate()-((now.getDay()+6)%7));const anchor=[monday.getFullYear(),String(monday.getMonth()+1).padStart(2,'0'),String(monday.getDate()).padStart(2,'0')].join('-');
 const days=['월','화','수','목','금','토','일'].map((d,i)=>({d,n:i+1,board:{sched:'훈련'},trainings:[]}));days[0].trainings=[{slot:'original',time:'17:00',grp:['A팀'],note:'기존 세션',blocks:[]}];
 const initial={version:1,anchorMonday:anchor,scheduleRev:1,weeks:{0:days}};
 const seed=`(()=>{const uid='fixture-team-picker',wid='fixture-team';if(!localStorage.getItem('fixture-team-seeded')){localStorage.setItem('fixture-team-seeded','1');localStorage.setItem('ps_sync_session',JSON.stringify({uid,at:'fixture',rt:'fixture'}));localStorage.setItem('ps_active_ws',wid);localStorage.setItem('ps_cache_owner_v1',JSON.stringify({uid,wid}));localStorage.setItem('ps_ws_list',JSON.stringify([{id:wid,kind:'team',role:'owner'}]));localStorage.setItem('cs_perms_v1',JSON.stringify({members:{[uid]:{role:'executive'}}}));localStorage.setItem('scout_tool_v1',JSON.stringify({players:[],meta:{grpBase:['A팀','B팀','C팀']}}));localStorage.setItem('process_coach_v1',JSON.stringify(${JSON.stringify(initial)}));localStorage.setItem('cs_wkmode','ses');}window.PSSync={session:()=>({uid}),activeWs:()=>wid,activeWsObj:()=>({id:wid,kind:'team',role:'owner'}),dataUnlocked:()=>true,keyReady:()=>true,syncNow:()=>Promise.resolve({fixture:true}),act(){},ping(){}};})();`;
 return function(url){const f=path.resolve(root,'.'+new URL(url,'http://localhost').pathname);if(!f.startsWith(root+path.sep))return null;try{let body=fs.readFileSync(f);if(f.endsWith('/studio/process.html'))body=Buffer.from(body.toString().replace('<script src="storage.js">','<script>'+seed+'</script><script src="storage.js">')+'<script>document.addEventListener("DOMContentLoaded",()=>{wk=0;week=weeksMap[0];dayIdx=0;go("schedule");setWkMode("ses");syncViews(false);});</script>');return {body,contentType:({'.html':'text/html; charset=utf-8','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.woff2':'font/woff2'})[path.extname(f)]||'application/octet-stream'};}catch{return null;}};
};
